<style id="gia-jason-style">
.clinical-launcher{
  position:fixed;
  right:18px;
  bottom:18px;
  z-index:190;
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  gap:10px;
}
.clinical-fab.clinical-fab-jason{
  position:relative;
  right:auto;
  bottom:auto;
  width:118px;
  height:118px;
  padding:0;
  border-radius:50%;
  background:#1590ff;
  box-shadow:0 20px 45px rgba(0,0,0,.26);
  display:grid;
  place-items:center;
  border:0;
  overflow:hidden;
}
.clinical-fab.clinical-fab-jason::before{
  content:"";
  position:absolute;
  inset:-6px;
  border-radius:50%;
  border:2px solid rgba(21,144,255,.28);
  animation:guidePulse 2.4s ease-out infinite;
}
.clinical-fab.clinical-fab-jason:hover{
  transform:translateY(-4px) scale(1.03);
  box-shadow:0 25px 55px rgba(0,0,0,.32);
}
.clinical-fab.clinical-fab-jason .clinical-avatar{
  width:82px;
  height:82px;
  border-radius:50%;
  border:0;
  background:#eaf3ff;
  box-shadow:none;
  overflow:hidden;
}
.clinical-fab.clinical-fab-jason .clinical-avatar img{
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:50% 28%;
  transform:scale(1.06);
}
.clinical-fab.clinical-fab-jason .clinical-fab-text{
  display:none !important;
}
.clinical-greeting{
  position:relative;
  max-width:300px;
  background:#fff;
  color:#1c1c1c;
  border-radius:18px;
  padding:16px 46px 16px 20px;
  box-shadow:0 14px 34px rgba(0,0,0,.18);
  font-size:14px;
  line-height:1.45;
}
.clinical-greeting p{
  margin:0;
  font-size:14px;
  line-height:1.45;
  font-weight:500;
}
.clinical-greeting::after{
  content:"";
  position:absolute;
  right:30px;
  bottom:-12px;
  width:22px;
  height:22px;
  background:#fff;
  transform:rotate(45deg);
  border-radius:4px;
}
.clinical-greeting-close{
  position:absolute;
  top:8px;
  right:10px;
  width:24px;
  height:24px;
  border:0;
  border-radius:50%;
  background:#f1f4f8;
  color:#5b6773;
  font-size:16px;
  line-height:1;
  cursor:pointer;
}
.clinical-greeting.hidden{
  display:none;
}
@media (max-width:620px){
  .clinical-launcher{
    right:12px;
    bottom:12px;
    gap:8px;
  }
  .clinical-greeting{
    max-width:232px;
    padding:14px 40px 14px 16px;
    border-radius:16px;
    font-size:13px;
  }
  .clinical-greeting p{
    font-size:13px;
  }
  .clinical-greeting::after{
    right:20px;
    bottom:-10px;
    width:18px;
    height:18px;
  }
  .clinical-fab.clinical-fab-jason{
    width:96px;
    height:96px;
  }
  .clinical-fab.clinical-fab-jason .clinical-avatar{
    width:68px;
    height:68px;
  }
}
</style>
