function manualSearchScore(m,q){const nq=manualNorm(q);if(!nq)return 1;const toks=manualTokens(nq);const aliases=(MANUAL_SEARCH_ALIASES[m.id]||[]).map(manualNorm);const meta=manualNorm([m.title,m.subtitle,m.category,m.source,m.status,m.note,...aliases].join(' '));let score=0;if(meta.includes(nq))score+=150;for(const t of toks){if(manualFuzzyHit(meta,t))score+=35}const pageMap=ensureManualContentIndex();if(pageMap&&pageMap[m.file]){let best=0;for(const h of pageMap[m.file]){let hit=0;if(h.includes(nq))hit+=90;for(const t of toks)if(manualFuzzyHit(h,t))hit+=18;best=Math.max(best,hit)}score+=best}return score}

