function bindManualOpen(){
  document.addEventListener('click',async e=>{
    const a=e.target.closest('[data-open-manual]');
    if(!a)return;
    const id=a.getAttribute('data-open-manual');
    const m=MANUALS.find(x=>x.id===id);
    if(!m)return;
    const local=m.file||'';
    if(!local || /^https?:\/\//i.test(local))return;
    e.preventDefault();
    const tab=window.open('about:blank','_blank');
    try{
      const r=await fetch(local,{method:'HEAD',cache:'no-store'});
      const target=r.ok?local:(MANUAL_FALLBACKS[id]||m.url||local);
      if(tab)tab.location.href=target; else window.location.href=target;
    }catch(err){
      const target=MANUAL_FALLBACKS[id]||m.url||local;
      if(tab)tab.location.href=target; else window.location.href=target;
    }
  },true);
}
